package dev.sablelife.testing;

import java.util.*;
import dev.sablelife.SableLife;
import dev.sablelife.heart.*;
import dev.sablelife.module.*;
import dev.sablelife.ownership.LoadedCoreIndex;
import dev.sablelife.compat.sable.SableBodyProbe;
import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;
import dev.ryanhcode.sable.companion.math.BoundingBox3i;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.neoforged.neoforge.gametest.*;

@GameTestHolder("sablelife_priority_tests") @PrefixGameTestTemplate(false)
public final class TargetPriorityGameTests {
    private static HeartBlockEntity core(GameTestHelper h,int offset){var l=h.getLevel();var p=h.absolutePos(new BlockPos(4+offset,40,4));l.setBlockAndUpdate(p,SableLife.HEART.get().defaultBlockState());l.setBlockAndUpdate(p.east(),Blocks.IRON_BLOCK.defaultBlockState());var body=SubLevelAssemblyHelper.assembleBlocks(l,p,List.of(p,p.east()),new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX()+1,p.getY(),p.getZ()));var c=(HeartBlockEntity)l.getBlockEntity(body.getPlot().getCenterBlock());LoadedCoreIndex.observe(c);return c;}
    private static net.neoforged.neoforge.common.util.FakePlayer player(GameTestHelper h,Vec3 position){var p=TestActors.creative(h.getLevel());p.setGameMode(GameType.SURVIVAL);p.setNoGravity(true);h.getLevel().addNewPlayer(p);p.setPos(position);return p;}
    @GameTest(template="combat",batch="priority_aim")
    public static void AllPrefersPlayersAndFallsBackAfterExclusionAndTypeFiltering(GameTestHelper h){var c=core(h,0);var m=c.modules().add("gun");m.anchors(List.of(ModuleAnchor.create(c,c.getBlockPos(),Direction.NORTH)));m.edit("shotAim",1,"");m.edit("target",2,"");m.edit("targetRange",16,"");var start=ModuleCombat.nozzle(c,m);var cow=EntityType.COW.create(h.getLevel());cow.setNoAi(true);cow.setNoGravity(true);cow.setPos(start.add(2,0,0));h.getLevel().addFreshEntity(cow);var p=player(h,start.add(0,0,5));
        h.assertTrue(ProjectileAim.directions(c,m,start).getFirst().x>.8,"Default nearest changed");c.relations().priority(1);h.assertTrue(ProjectileAim.directions(c,m,start).getFirst().z>.8,"Player priority ignored by projectile aiming");m.edit("targetMultiple",1,"");var many=ProjectileAim.directions(c,m,start);h.assertTrue(many.size()==2&&many.getFirst().z>.8,"Multiple mode dropped lower priority target or order");m.edit("targetMultiple",0,"");c.relations().exclude(p.getGameProfile().getName());h.assertTrue(ProjectileAim.directions(c,m,start).getFirst().x>.8,"Priority bypassed player exclusion");c.relations().remove(p.getGameProfile().getName());m.edit("target",1,"");h.assertTrue(ProjectileAim.directions(c,m,start).getFirst().x>.8,"Priority added a player outside configured target type");p.discard();cow.discard();h.succeed();}
    @GameTest(template="combat",batch="priority_facing")
    public static void LifePriorityRespectsFactionsAndMobPriorityRespectsDistance(GameTestHelper h){var c=core(h,0);var life=core(h,8);life.tryActivate(TestActors.creative(h.getLevel()));LoadedCoreIndex.observe(life);var pivot=SableBodyProbe.toWorld(h.getLevel(),c.getBlockPos().getCenter()).add(0,1,0);var cow=EntityType.COW.create(h.getLevel());cow.setNoAi(true);cow.setNoGravity(true);cow.setPos(pivot.add(2,0,0));h.getLevel().addFreshEntity(cow);var p=player(h,pivot.add(0,0,4));var facing=c.modules().add("auto_facing");facing.edit("target",2,"");facing.edit("facingRange",16,"");c.relations().priority(2);h.assertTrue(ModuleAutoFacing.selectTarget(h.getLevel(),c,facing,pivot).getUUID().equals(life.creatureId()),"Life priority not applied to auto facing");var owner=TestActors.creative(h.getLevel());var faction=FactionRegistry.get(h.getLevel().getServer()).create(owner,"P"+UUID.randomUUID().toString().substring(0,8));c.relations().faction(faction);life.relations().faction(faction);h.assertTrue(ModuleAutoFacing.selectTarget(h.getLevel(),c,facing,pivot).getUUID().equals(cow.getUUID()),"Preferred ally bypassed faction filtering");c.relations().priority(1);h.assertTrue(ModuleAutoFacing.selectTarget(h.getLevel(),c,facing,pivot).getUUID().equals(p.getUUID()),"Player priority missing");c.relations().priority(3);h.assertTrue(ModuleAutoFacing.selectTarget(h.getLevel(),c,facing,pivot).getUUID().equals(cow.getUUID()),"Mob priority missing");p.discard();cow.discard();h.succeed();}
    @GameTest(template="combat",batch="priority_cache")
    public static void SummonCacheAppliesPriorityOnlyWhenReselectingAndFallsBack(GameTestHelper h){var c=core(h,0);var origin=SableBodyProbe.toWorld(h.getLevel(),c.getBlockPos().getCenter()).add(0,2,0);var cow=EntityType.COW.create(h.getLevel());cow.setNoAi(true);cow.setNoGravity(true);cow.setPos(origin.add(2,0,0));h.getLevel().addFreshEntity(cow);var p=player(h,origin.add(0,0,5));var cache=new SummonTargetCache();c.relations().priority(1);cache.prepare(h.getLevel(),c.creatureId(),2,List.of(origin),16,0);h.assertTrue(cache.select(null,origin,16,true).equals(p.getUUID()),"Formation cache ignored priority");h.assertTrue(cache.select(cow.getUUID(),origin,16,false).equals(cow.getUUID()),"Priority broke target lock");c.relations().exclude(p.getGameProfile().getName());cache.prepare(h.getLevel(),c.creatureId(),2,List.of(origin),16,1);h.assertTrue(cache.select(null,origin,16,true).equals(cow.getUUID()),"Cached excluded player stayed preferred");p.discard();cow.discard();h.succeed();}
    @GameTest(template="combat",batch="priority_save")
    public static void SettingsPersistCopyAndValidatePermissionsAndLegacyDefaults(GameTestHelper h){var c=core(h,0);var p=TestActors.creative(h.getLevel());p.setPos(SableBodyProbe.toWorld(h.getLevel(),c.getBlockPos().getCenter()));var menu=new HeartSettingsMenu(1,p.getInventory(),c);h.assertTrue(c.relations().priority()==0,"Legacy/default priority changed");h.assertTrue(menu.action(p,"targetPriority",2,"")&&menu.snapshot().getInt("targetPriority")==2,"Core settings did not sync priority");var saved=c.copyConfiguration();h.assertTrue(saved.getCompound("Relations").getInt("TargetPriority")==2,"Clipboard lost priority");var restored=new CoreRelations();restored.load(c.relations().save());h.assertTrue(restored.priority()==2,"Priority lost on reload");restored.load(new net.minecraft.nbt.CompoundTag());h.assertTrue(restored.priority()==0,"Old core did not default to nearest");h.assertTrue(!menu.action(p,"targetPriority",4,"")&&!menu.action(p,"targetPriority",1.5,""),"Invalid priority accepted");p.setGameMode(GameType.SURVIVAL);h.assertTrue(!menu.action(p,"targetPriority",1,"")&&c.relations().priority()==2,"Survival changed life-core priority");h.succeed();}
}
